type fileEntry struct {
	name    string
	content []byte
}

func makeFS(t *testing.T, fe []fileEntry) {
	fs = afero.NewMemMapFs()

	for _, f := range fe {
		err := afero.WriteFile(fs, f.name, f.content, 0444)
		require.NoError(t, err)
	}
}

func hexDecode(s string) ([]byte, error) {
	// allow a long hex string to be split over multiple lines (with soft or
	// hard tab indentation)
	m := regexp.MustCompile("[ \t\n]")
	s = m.ReplaceAllString(s, "")

	data, err := hex.DecodeString(s)
	if err != nil {
		return nil, err
	}
	return data, nil
}

func mustHexDecode(s string) []byte {
	data, err := hexDecode(s)
	if err != nil {
		panic(err)
	}
	return data
}

